"""Reviewed bilingual film companions, following the published narration order.

Times are approximate chapter/segment starts, rounded down from audio/timing.json.
These editorial companions intentionally include qualifications the short films omit.
They do not require the private film-production source to build the public course.
"""


def tr(en, zh):
    return {"en": en, "zh": zh}


def step(at, title_en, title_zh, text_en, text_zh, detail=None):
    return dict(at=at, title=tr(title_en, title_zh), text=tr(text_en, text_zh), detail=detail)


def p(en, zh):
    return dict(kind="p", text=tr(en, zh))


def eq(text):
    return dict(kind="equation", text=text)


def bridge(id, at, title_en, title_zh, *blocks, demo=False):
    return dict(id=id, at=at, title=tr(title_en, title_zh), blocks=blocks, demo=demo)


